Object.assign(translations.zh,{realExampleLabel:'真实结果 · tornado',realExample:'公开结果显示 GA 为 3.23×，相同调用次数下最佳独立尝试为 1.57×。这是组合效应的证据，不是普遍证明。'});
Object.assign(translations.ja,{realExampleLabel:'実結果 · tornado',realExample:'公開結果では、同じ呼び出し数で GA は 3.23×、最良の独立試行は 1.57×でした。これは組み合わせの証拠であり、普遍的な証明ではありません。'});
Object.assign(translations.pt,{rinhaResultTitle:'Caso de pesquisa · Rinha de Backend',rinhaResult:'Em uma rodada isolada, o HypEvolve pesquisou 13 hipóteses, avaliou 7 implementações em 2 gerações e selecionou H3. O transcript do candidato reportou busca exata 2,84× mais rápida com 100 mil vetores sintéticos e 2,42× com 1 milhão, sem divergências em cerca de 20 mil consultas sintéticas. Em comparação pareada posterior, HypEvolve H1 ficou 27,8% mais rápido que sua referência e Codex direto, usando o mesmo prompt, 4,2% — apenas uma implementação por braço, portanto sem prova causal. São microbenchmarks, não o workload completo. A meta de p99 &lt; 0,4227 ms não foi atingida: na tentativa oficial, o p99 foi 2.119,657 ms (baseline: 2.007,521 ms), com muitos erros HTTP.'});
Object.assign(translations.en,{rinhaResultTitle:'Research case · Rinha de Backend',rinhaResult:'In an isolated run, HypEvolve explored 13 hypotheses, evaluated 7 implementations over 2 generations, and selected H3. The candidate transcript reported exact search 2.84× faster on 100k synthetic vectors and 2.42× on 1M, with no mismatches across about 20k synthetic queries. In a later matched comparison, HypEvolve H1 was 27.8% faster than its reference, while direct Codex with the same prompt was 4.2% faster — one implementation per arm, so this is not causal proof. These are microbenchmarks, not the full workload. The p99 < 0.4227 ms target was not met: in the official-workload attempt, p99 was 2,119.657 ms (baseline: 2,007.521 ms), with many HTTP errors.'});
Object.assign(translations.es,{rinhaResultTitle:'Caso de investigación · Rinha de Backend',rinhaResult:'En una ejecución aislada, HypEvolve exploró 13 hipótesis, evaluó 7 implementaciones en 2 generaciones y seleccionó H3. El transcript del candidato reportó una búsqueda exacta 2,84× más rápida con 100 mil vectores sintéticos y 2,42× con 1 millón, sin discrepancias en unas 20 mil consultas sintéticas. En una comparación emparejada posterior, HypEvolve H1 fue un 27,8 % más rápido que su referencia y Codex directo con el mismo prompt, un 4,2 % —solo una implementación por brazo, por lo que no es prueba causal. Son microbenchmarks, no el workload completo. No se alcanzó la meta de p99 < 0,4227 ms: en el intento con el workload oficial, el p99 fue de 2.119,657 ms (baseline: 2.007,521 ms), con muchos errores HTTP.'});
Object.assign(translations.zh,{rinhaResultTitle:'研究案例 · Rinha de Backend',rinhaResult:'在一次隔离运行中，HypEvolve 探索了 13 个假设，在 2 代中评估了 7 个实现，并选出 H3。候选记录报告：在 10 万个合成向量上，精确搜索快 2.84 倍；在 100 万个向量上快 2.42 倍；约 2 万次合成查询未发现不匹配。后续配对比较中，HypEvolve H1 比自身基准快 27.8%，使用相同提示词的直接 Codex 快 4.2%——每组仅一个实现，因此不能证明因果关系。这些是微基准，并非完整 workload。p99 < 0.4227 毫秒目标未达成：尝试官方 workload 时，p99 为 2,119.657 毫秒（baseline：2,007.521 毫秒），且出现大量 HTTP 错误。'});
Object.assign(translations.ja,{rinhaResultTitle:'研究事例 · Rinha de Backend',rinhaResult:'隔離実行で HypEvolve は13件の仮説を探索し、2世代で7実装を評価して H3 を選択しました。候補の記録では、合成ベクトル10万件で厳密検索が2.84倍、100万件で2.42倍高速となり、約2万件の合成クエリで不一致なしと報告されています。その後の対応比較では HypEvolve H1 は基準より27.8%高速、同じプロンプトを使った Codex 直接呼び出しは4.2%高速でした。各条件1実装のみで、因果的な証明ではありません。これはマイクロベンチマークであり、全 workload ではありません。p99 < 0.4227 ms の目標は未達です。公式 workload の実行を試みた際の p99 は 2,119.657 ms（baseline: 2,007.521 ms）で、多数の HTTP エラーがありました。'});
Object.assign(translations.pt,{alphaLead:'Um ganho isolado pode ser sorte. O portão ajuda a separar um sinal consistente do ruído, sem transformar significância em prova absoluta.',alphaObservedTitle:'Um número maior não basta',alphaObservedBody:'Uma execução pode ter sorte. Ganho observado é um sinal para investigar, não uma confirmação.',alphaSignificantTitle:'Consistência merece prioridade',alphaSignificantBody:'Quando o ganho se repete com pouca oscilação, fica mais plausível que ele sobreviva a novas execuções.',alphaConfirmedTitle:'Avanço para promover',alphaConfirmedBody:'A decisão ainda depende de efeito relevante, método adequado e replicação.',alphaMeaningBody:'α=0,05 é um limite combinado antes da análise. Ele ajuda a decidir quando uma diferença parece maior que o ruído.',alphaPassNote:'evidência suficiente no teste',alphaFailNote:'ainda não convence; não prova ausência de melhoria',alphaCaveat:'Alpha não é o ganho mínimo, a variabilidade nem a probabilidade de a hipótese ser verdadeira.',pValueLabel:'valor-p',demoCaption:'O valor-p resume quão compatíveis os resultados são com “nenhuma melhoria”: quanto menor, menos provável que a diferença seja apenas ruído. Ele não é a probabilidade de a hipótese ser verdadeira. Dados sintéticos; não são resultados da pesquisa.',stableFocusTitle:'Por que favorecer a estabilidade?',stableFocusBody:'Os dois candidatos chegam a +5% na média, mas B oscila muito. Olhar apenas para o melhor número pode promover sorte; priorizar resultados consistentes aumenta a chance de uma melhoria sobreviver a novas execuções. B não é tratado como campeão validado.',demoProgress:'Ainda faltam execuções para comparar a consistência.',demoFinal:'A tem p={pa} e B tem p={pb}. A é consistente o bastante para passar neste exemplo; B não é promovido como melhoria validada.',resume:'Continuar',methodTitle:'Como isso se conecta ao Hypevolve',methodLead:'A demonstração é educativa e não altera o pipeline real.',methodShort:'Hoje, o Hypevolve repete os benchmarks 9 vezes, compara os tempos do candidato ao baseline e usa essa evidência para registrar speedup e significância. A página ajuda a entender por que consistência importa; correções para múltiplas comparações e validação independente posterior ainda não estão implementadas.',realExampleLabel:'Resultado real · tornado',realExample:'O resultado publicado foi 3,23× para o GA contra 1,57× da melhor tentativa independente com as mesmas chamadas. É evidência de composição, não prova universal.'});
Object.assign(translations.en,{alphaLead:'A single gain may be luck. The gate helps separate a consistent signal from noise without turning significance into absolute proof.',alphaObservedTitle:'A bigger number is not enough',alphaObservedBody:'One run can be lucky. An observed gain is a signal to investigate, not confirmation.',alphaSignificantTitle:'Consistency deserves priority',alphaSignificantBody:'When a gain repeats with little variation, it is more plausible that it will survive new runs.',alphaConfirmedTitle:'An advance worth promoting',alphaConfirmedBody:'The decision still depends on a relevant effect, adequate method, and replication.',alphaMeaningBody:'α=0.05 is a threshold agreed before analysis. It helps decide when a difference looks larger than noise.',alphaPassNote:'enough evidence in this test',alphaFailNote:'not convincing yet; does not prove no improvement',alphaCaveat:'Alpha is not the minimum gain, result variability, or the probability that a hypothesis is true.',pValueLabel:'p-value',demoCaption:'The p-value summarizes how compatible the results are with “no improvement”: the smaller it is, the less likely the difference is just noise. It is not the probability that the hypothesis is true. Synthetic data; not research results.',stableFocusTitle:'Why favor stability?',stableFocusBody:'Both candidates average +5%, but B swings widely. Looking only at the best number can promote luck; prioritizing consistent results makes an improvement more likely to survive new runs. B is not promoted as a validated champion.',demoProgress:'More runs are needed to compare consistency.',demoFinal:'A has p={pa} and B has p={pb}. A is consistent enough to pass in this example; B is not promoted as a validated improvement.',resume:'Resume',methodTitle:'How this connects to Hypevolve',methodLead:'This demonstration is educational and does not change the real pipeline.',methodShort:'Hypevolve currently repeats benchmarks 9 times, compares candidate times with the baseline, and uses that evidence to record speedup and significance. This page explains why consistency matters; multiple-comparison correction and independent post-validation are not implemented yet.',realExampleLabel:'Real result · tornado',realExample:'The published result was 3.23× for the GA versus 1.57× for the best independent attempt with the same calls. It is evidence of composition, not universal proof.'});
Object.assign(translations.es,{alphaLead:'Una ganancia aislada puede ser suerte. La puerta ayuda a separar una señal consistente del ruido sin convertir la significación en prueba absoluta.',alphaObservedTitle:'Un número mayor no basta',alphaObservedBody:'Una ejecución puede tener suerte. Una ganancia observada es una señal para investigar, no una confirmación.',alphaSignificantTitle:'La consistencia merece prioridad',alphaSignificantBody:'Cuando la ganancia se repite con poca variación, es más plausible que sobreviva a nuevas ejecuciones.',alphaConfirmedTitle:'Un avance que merece promoción',alphaConfirmedBody:'La decisión también depende de un efecto relevante, un método adecuado y replicación.',alphaMeaningBody:'α=0,05 es un umbral acordado antes del análisis. Ayuda a decidir cuándo una diferencia parece mayor que el ruido.',alphaPassNote:'evidencia suficiente en este test',alphaFailNote:'todavía no convence; no prueba ausencia de mejora',alphaCaveat:'Alpha no es la ganancia mínima, la variabilidad ni la probabilidad de que la hipótesis sea verdadera.',pValueLabel:'valor p',demoCaption:'El valor p resume cuán compatibles son los resultados con “ninguna mejora”: cuanto menor, menos probable que la diferencia sea solo ruido. No es la probabilidad de que la hipótesis sea verdadera. Datos sintéticos; no son resultados de la investigación.',stableFocusTitle:'¿Por qué favorecer la estabilidad?',stableFocusBody:'Ambos candidatos promedian +5%, pero B oscila mucho. Mirar solo el mejor número puede promover la suerte; priorizar resultados consistentes aumenta la posibilidad de que una mejora sobreviva a nuevas ejecuciones. B no se promueve como mejora validada.',demoProgress:'Aún faltan ejecuciones para comparar la consistencia.',demoFinal:'A tiene p={pa} y B tiene p={pb}. A es suficientemente consistente para pasar en este ejemplo; B no se promueve como mejora validada.',resume:'Continuar',methodTitle:'Cómo se conecta con Hypevolve',methodLead:'La demostración es educativa y no cambia el pipeline real.',methodShort:'Hypevolve repite hoy los benchmarks 9 veces, compara los tiempos del candidato con el baseline y usa esa evidencia para registrar speedup y significación. La página explica por qué importa la consistencia; todavía no implementa corrección por comparaciones múltiples ni validación independiente posterior.',realExampleLabel:'Resultado real · tornado',realExample:'El resultado publicado fue 3,23× para el GA frente a 1,57× del mejor intento independiente con las mismas llamadas. Es evidencia de composición, no una prueba universal.'});
Object.assign(translations.zh,{alphaLead:'一次孤立的提升可能只是运气。门控帮助区分一致的信号与噪声，但不会把显著性变成绝对证明。',alphaObservedTitle:'数字更大还不够',alphaObservedBody:'一次运行可能碰巧更好。观察到的提升是需要调查的信号，不是确认。',alphaSignificantTitle:'一致性值得优先',alphaSignificantBody:'如果提升在波动很小时重复出现，它更可能经得起新的运行。',alphaConfirmedTitle:'值得提升的进展',alphaConfirmedBody:'决定还需要相关效应、合适的方法和复现。',alphaMeaningBody:'α=0.05 是分析前约定的阈值，用来判断差异是否看起来大于噪声。',alphaPassNote:'此检验中的证据足够',alphaFailNote:'暂时不够有说服力；不证明没有改进',alphaCaveat:'Alpha 不是最小收益、结果波动性，也不是假设为真的概率。',pValueLabel:'p 值',demoCaption:'p 值概括结果与“没有改进”是否相容：越小，差异越不可能只是噪声。它不是假设为真的概率。合成数据，不是研究结果。',stableFocusTitle:'为什么偏好稳定性？',stableFocusBody:'两位候选者平均都是 +5%，但 B 波动很大。只看最高数字可能会提升运气；优先考虑一致结果，更有机会经受新的运行。B 不会被提升为已验证改进。',demoProgress:'还需要更多运行来比较一致性。',demoFinal:'A 的 p={pa}，B 的 p={pb}。在这个例子中 A 足够一致而通过；B 不会被提升为已验证改进。',resume:'继续',methodTitle:'这与 Hypevolve 的关系',methodLead:'此演示用于教育，不会改变真实流程。',methodShort:'Hypevolve 当前将基准重复 9 次，把候选时间与基线比较，并用证据记录 speedup 和显著性。本页说明一致性为何重要；当前尚未实现多重比较校正或独立的后续验证。',realExampleLabel:'真实结果 · tornado',realExample:'公开结果显示 GA 为 3.23×，相同调用次数下最佳独立尝试为 1.57×。这是组合效应的证据，不是普遍证明。'});
Object.assign(translations.ja,{alphaLead:'1回だけの改善は幸運かもしれません。ゲートは一貫した信号とノイズを分けますが、有意性を絶対的な証明にはしません。',alphaObservedTitle:'数字が大きいだけでは不十分',alphaObservedBody:'1回の実行が幸運だった可能性があります。観測された改善は調査の手がかりであり、確認ではありません。',alphaSignificantTitle:'一貫性を優先する',alphaSignificantBody:'ばらつきが小さいまま改善が繰り返されるほど、新しい実行にも耐える可能性が高まります。',alphaConfirmedTitle:'昇格に値する進歩',alphaConfirmedBody:'判断には意味のある効果、適切な方法、再現性も必要です。',alphaMeaningBody:'α=0.05 は分析前に合意する閾値です。差がノイズより大きく見えるかを判断する助けになります。',alphaPassNote:'この検定では十分な証拠',alphaFailNote:'まだ不十分で、改善がない証明ではありません',alphaCaveat:'Alpha は最小改善、結果の変動、仮説が真である確率ではありません。',pValueLabel:'p値',demoCaption:'p値は、結果が「改善なし」とどの程度整合するかを表します。小さいほど差が単なるノイズである可能性が低いという意味です。仮説が真である確率ではありません。合成データであり研究結果ではありません。',stableFocusTitle:'なぜ一貫性を優先するのか？',stableFocusBody:'両候補の平均は +5% ですが、B は大きく揺れます。最高値だけを見ると幸運を昇格させる可能性があります。一貫した結果を優先すれば、新しい実行にも耐える改善を選びやすくなります。B は検証済み改善として昇格しません。',demoProgress:'一貫性を比べるには、さらに実行が必要です。',demoFinal:'A の p は {pa}、B は {pb} です。この例では A は通過できる一貫性があり、B は検証済み改善として昇格しません。',resume:'再開',methodTitle:'Hypevolve とのつながり',methodLead:'このデモは教育用で、実際のパイプラインを変更しません。',methodShort:'現在の Hypevolve はベンチマークを9回繰り返し、候補の時間を baseline と比較し、その証拠から speedup と有意性を記録します。このページは一貫性の重要性を説明します。多重比較補正と独立した事後検証はまだ実装されていません。',realExampleLabel:'実結果 · tornado',realExample:'公開結果では、同じ呼び出し数で GA は 3.23×、最良の独立試行は 1.57×でした。これは組み合わせの証拠であり、普遍的な証明ではありません。'});
let activeLanguage='pt';
const alphaText=key=>(translations[activeLanguage]||translations.pt)[key]||key;
function erf(x){const sign=x<0?-1:1;const a1=.254829592,a2=-.284496736,a3=1.421413741,a4=-1.453152027,a5=1.061405429,p=.3275911;const t=1/(1+p*Math.abs(x));return sign*(1-((((a5*t+a4)*t+a3)*t+a2)*t+a1)*t*Math.exp(-x*x))}
const normalCdfSafe=x=>0.5*(1+erf(x/Math.sqrt(2)));
function mannWhitneyGreater(x,y){const all=x.concat(y).sort((a,b)=>a-b);const ranks=new Map();let i=0;while(i<all.length){let j=i+1;while(j<all.length&&all[j]===all[i])j++;const rank=(i+j+1)/2;for(let k=i;k<j;k++)ranks.set(`${all[k]}:${k}`,rank);i=j}const rankSum=x.reduce((sum,value,index)=>sum+(ranks.get(`${value}:${all.indexOf(value)}`)||0),0);const n1=x.length,n2=y.length,N=n1+n2,U=rankSum-n1*(n1+1)/2,mean=n1*n2/2;const counts={};all.forEach(v=>{counts[v]=(counts[v]||0)+1});const tie=Object.values(counts).reduce((sum,t)=>sum+t*t*t-t,0);const variance=n1*n2/12*(N+1-tie/(N*(N-1)));return 1-normalCdfSafe((U-mean-.5)/Math.sqrt(variance))}
function sampleSd(values){if(values.length<2)return 0;const mean=values.reduce((a,b)=>a+b,0)/values.length;return Math.sqrt(values.reduce((s,v)=>s+(v-mean)**2,0)/(values.length-1))}
function fmtP(value){return value===null||Number.isNaN(value)?'—':value<.0001?'<0.0001':value.toFixed(4)}
function fmtPct(value){return `${value>=0?'+':''}${value.toFixed(1)}%`}
const alphaCandidates={a:[4,5,6,5,5],b:[-15,25,-10,20,5]};let alphaDemoIndex=0,alphaDemoPaused=false,alphaTimer=null;
function candidateSvg(values,visible,accent){const w=520,h=190,p={l:30,r:15,t:15,b:30},min=-20,max=30,x=i=>p.l+i*(w-p.l-p.r)/4,y=v=>h-p.b-(v-min)*(h-p.t-p.b)/(max-min),svg=svgEl('svg',{viewBox:`0 0 ${w} ${h}`,role:'img'});svg.append(svgEl('line',{x1:p.l,x2:w-p.r,y1:y(0),y2:y(0),stroke:'#668198','stroke-dasharray':'4 4'}));[-20,0,30].forEach(v=>svg.append(svgEl('text',{x:5,y:y(v)+4,fill:'#8399ad','font-size':10,'font-family':'DM Mono'},`${v}%`)));values.forEach((v,i)=>{if(i>=visible)return;svg.append(svgEl('line',{x1:x(i),x2:x(i),y1:y(0),y2:y(v),stroke:accent,'stroke-width':2,'stroke-opacity':.65}),svgEl('circle',{cx:x(i),cy:y(v),r:6,fill:accent}));svg.append(svgEl('text',{x:x(i),y:h-8,'text-anchor':'middle',fill:'#9eb0c2','font-size':10,'font-family':'DM Mono'},`${i+1}`))});if(visible===values.length){const mean=values.reduce((a,b)=>a+b,0)/values.length;svg.append(svgEl('line',{x1:p.l,x2:w-p.r,y1:y(mean),y2:y(mean),stroke:'#eaf2ff','stroke-width':1,'stroke-dasharray':'2 3'}))}return svg}
function updateCandidate(id,values,accent){const visible=Math.min(alphaDemoIndex,values.length),root=document.getElementById(`candidate-${id}-chart`);root.replaceChildren(candidateSvg(values,visible,accent));const shown=values.slice(0,visible),mean=shown.length?shown.reduce((a,b)=>a+b,0)/shown.length:0,spread=sampleSd(shown),p=shown.length>1?mannWhitneyGreater(shown,new Array(shown.length).fill(0)):null;document.getElementById(`candidate-${id}-mean`).textContent=shown.length?fmtPct(mean):'—';document.getElementById(`candidate-${id}-spread`).textContent=shown.length>1?`${spread.toFixed(1)}%`:'—';document.getElementById(`candidate-${id}-p`).textContent=fmtP(p)}
function updateAlphaDemo(){updateCandidate('a',alphaCandidates.a,'#6cf0c2');updateCandidate('b',alphaCandidates.b,'#ffca6b');document.getElementById('alpha-demo-step').textContent=`${alphaDemoIndex} / 5`;document.querySelector('.candidate-unstable').classList.toggle('candidate-not-promoted',alphaDemoIndex===5);const explanation=document.getElementById('alpha-demo-explanation');if(alphaDemoIndex<5)explanation.textContent=`${alphaText('demoProgress')} ${alphaDemoIndex}/5`;else{const pa=mannWhitneyGreater(alphaCandidates.a,[0,0,0,0,0]),pb=mannWhitneyGreater(alphaCandidates.b,[0,0,0,0,0]);explanation.textContent=alphaText('demoFinal').replace('{pa}',fmtP(pa)).replace('{pb}',fmtP(pb))}}
function stepAlpha(delta){alphaDemoIndex=(alphaDemoIndex+delta+6)%6;if(alphaDemoIndex===5&&delta>0)alphaDemoIndex=5;updateAlphaDemo()}
function resetAlpha(){alphaDemoIndex=0;alphaDemoPaused=false;const button=document.querySelector('[data-alpha-action="toggle"]');if(button)button.textContent=alphaText('pause');updateAlphaDemo()}
function toggleAlpha(){alphaDemoPaused=!alphaDemoPaused;const button=document.querySelector('[data-alpha-action="toggle"]');if(button)button.textContent=alphaText(alphaDemoPaused?'resume':'pause')}
const logGamma=x=>{const cof=[76.18009172947146,-86.50532032941677,24.01409824083091,-1.231739572450155,.001208650973866179,-.000005395239384953];let y=x,tmp=x+5.5;tmp-=(x+.5)*Math.log(tmp);let ser=1.000000000190015;cof.forEach(c=>{y+=1;ser+=c/y});return -tmp+Math.log(2.5066282746310005*ser/x)};
function betaContinuedFraction(a,b,x){let qab=a+b,qap=a+1,qam=a-1,c=1,d=1-qab*x/qap;d=Math.abs(d)<1e-30?1e-30:d;d=1/d;let h=d;for(let m=1;m<=100;m++){const m2=2*m;let aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;d=Math.abs(d)<1e-30?1e-30:d;c=1+aa/c;c=Math.abs(c)<1e-30?1e-30:c;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;d=Math.abs(d)<1e-30?1e-30:d;c=1+aa/c;c=Math.abs(c)<1e-30?1e-30:c;d=1/d;const del=d*c;h*=del;if(Math.abs(del-1)<3e-7)break}return h}
function regularizedBeta(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const front=Math.exp(logGamma(a+b)-logGamma(a)-logGamma(b)+a*Math.log(x)+b*Math.log(1-x));return x<(a+1)/(a+b+2)?front*betaContinuedFraction(a,b,x)/a:1-front*betaContinuedFraction(b,a,1-x)/b}
function studentTCdf(t,df){if(t===0)return .5;const x=df/(df+t*t),ib=regularizedBeta(x,df/2,.5);return t>0?1-.5*ib:.5*ib}
const tCritical95=[4.303,3.182,2.776,2.571,2.447,2.365,2.306,2.262,2.228,2.201,2.179,2.160,2.145,2.131,2.120,2.110,2.101,2.093,2.086,2.080,2.074,2.069,2.064,2.060,2.056,2.052,2.048,2.045];
