document.addEventListener('DOMContentLoaded',()=>{const language=document.getElementById('language');language.addEventListener('change',e=>{applyLanguage(e.target.value);updateAlphaDemo()});applyLanguage(localStorage.getItem('hypevolve-language')||'pt');lineChart(document.getElementById('trajectory-tornado'));barChart(document.getElementById('comparison-tornado'),'tornado');document.querySelectorAll('[data-alpha-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.alphaAction;if(action==='prev')stepAlpha(-1);if(action==='next')stepAlpha(1);if(action==='toggle')toggleAlpha();if(action==='reset')resetAlpha()}));updateAlphaDemo();alphaTimer=setInterval(()=>{if(!alphaDemoPaused&&alphaDemoIndex<5){alphaDemoIndex+=1;updateAlphaDemo()}},1900);const steps=[...document.querySelectorAll('.generation-step')];let active=0;const animateGeneration=()=>{steps.forEach((step,index)=>step.classList.toggle('active',index===active));active=(active+1)%steps.length};animateGeneration();setInterval(animateGeneration,2200);const io=new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&e.target.classList.add('visible')),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>io.observe(e))});
